/**
 * Changes the workspace URL. The slug is taken exactly as given: a collision
 * is refused, never suffixed. The previous slug stays resolvable for
 * `ORG_SLUG_HOLD_DAYS`. Renaming to the slug the workspace already has is a
 * no-op — nothing is written and nothing is published.
 */
export async function renameOrganizationSlug(
  actor: Actor,
  input: RenameOrganizationSlugInput,
): Promise<Organization> {
  assertOrgScope(actor, input.orgId);
  assertCan(actor, "org:update", orgResource(input.orgId));

  const current = requireFound(
    await orgRepo.findOrgById(input.orgId),
    "Organization",
    input.orgId,
  );

  if (current.slug === input.slug) return current;

  assertValidSlug(input.slug);

  const updated = await orgRepo.renameOrgSlug(input.orgId, input.slug);

  // Recorded here, not by an event subscriber: a subscriber plus this write
  // would store the audit action twice whenever the bus is wired.
  await record(updated.id, "organization.slug_changed", {
    actorId: actor.userId,
    subjectKind: "organization",
    subjectId: updated.id,
    projectId: null,
    summary: `Slug ${current.slug} → ${updated.slug}`,
    metadata: { from: current.slug, to: updated.slug },
  });

  await emit("organization.slug_changed", {
    ...actorEnvelope(actor),
    from: current.slug,
    to: updated.slug,
  });

  return updated;
}

