function principal(tenant: Tenant): SessionPrincipal {
  return {
    userId: tenant.userIds.owner,
    email: "owner@test",
    activeOrgId: tenant.org.id,
    expiresAt: toIsoTimestamp("2030-01-01T00:00:00.000Z"),
  };
}

async function auditRows(tenant: Tenant) {
  return activityRepo.listActivity({
    orgId: tenant.org.id,
    action: ["organization.slug_changed"],
    limit: 25,
    cursor: null,
  });
}

describe("renameOrganizationSlug", () => {
  it("renames, keeps the old slug for the hold, and announces once", async () => {
    const tenant = await createTenant("rename-basic", "growth");
    const seen: TaskflowEventMap["organization.slug_changed"][] = [];
    const off = subscribe("organization.slug_changed", (payload) => {
      seen.push(payload);
    });
    const before = tenant.org;

    const updated = await renameOrganizationSlug(tenant.actors.admin, {
      orgId: tenant.org.id,
      slug: "rename-basic-next",
    });

    expect(updated.slug).toBe("rename-basic-next");
    expect(updated.name).toBe(before.name);
    expect(updated.plan).toBe(before.plan);
    expect(updated.ownerId).toBe(before.ownerId);
    expect(updated.logoUrl).toBe(before.logoUrl);
    expect(updated.settings).toEqual(before.settings);
    expect(updated.createdAt).toBe(before.createdAt);
    expect(updated.archivedAt).toBe(before.archivedAt);
    expect(updated.id).toBe(before.id);

    const summary = await getOrganizationSummary(tenant.actors.owner, tenant.org.id);
    expect(summary.organization.slug).toBe("rename-basic-next");

    const listed = await listOrganizationsForUser(tenant.userIds.owner);
    expect(listed.find((org) => org.id === tenant.org.id)?.slug).toBe(
      "rename-basic-next",
    );

    const byOld = await resolveOrgBySlug("rename-basic");
    const byNew = await resolveOrgBySlug("rename-basic-next");
    expect(byOld?.id).toBe(tenant.org.id);
    expect(byOld?.slug).toBe("rename-basic-next");
    expect(byNew?.slug).toBe("rename-basic-next");

    const actor = await resolveActorForOrg(principal(tenant), "rename-basic");
    expect(actor?.orgId).toBe(tenant.org.id);
    expect(actor?.userId).toBe(tenant.userIds.owner);

    expect(seen).toHaveLength(1);
    expect(seen[0]).toMatchObject({
      orgId: tenant.org.id,
      actorId: tenant.userIds.admin,
      from: "rename-basic",
      to: "rename-basic-next",
    });

    const page = await auditRows(tenant);
    expect(page.items).toHaveLength(1);
    expect(page.items[0]).toMatchObject({
      action: "organization.slug_changed",
      actorId: tenant.userIds.admin,
      subjectKind: "organization",
      subjectId: tenant.org.id,
      metadata: { from: "rename-basic", to: "rename-basic-next" },
    });

    off();
  });

  it("is a no-op when the slug does not change", async () => {
    const tenant = await createTenant("rename-noop", "growth");
    const seen: unknown[] = [];
    const off = subscribe("organization.slug_changed", (payload) => {
      seen.push(payload);
    });
    const before = await orgRepo.findOrgById(tenant.org.id);

    const updated = await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rename-noop",
    });

    expect(updated).toEqual(before);
    expect(seen).toHaveLength(0);
    expect((await auditRows(tenant)).items).toHaveLength(0);
    off();
  });

  it("refuses a slug another workspace holds and a bad slug, changing nothing", async () => {
    const tenant = await createTenant("rename-taken", "growth");
    const other = await createTenant("rename-other", "growth");

    await expect(
      renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: "rename-other",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    await expect(
      renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: "settings",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    await expect(
      renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: "Not A Slug",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    const stored = await orgRepo.findOrgById(tenant.org.id);
    expect(stored?.slug).toBe("rename-taken");
    expect(stored?.updatedAt).toBe(tenant.org.updatedAt);
    expect((await auditRows(tenant)).items).toHaveLength(0);

    await orgRepo.archiveOrg(other.org.id);
    await expect(
      renameOrganizationSlug(tenant.actors.owner, {
        orgId: tenant.org.id,
        slug: "rename-other",
      }),
    ).rejects.toBeInstanceOf(InvalidSlugError);
    expect((await orgRepo.findOrgById(tenant.org.id))?.slug).toBe("rename-taken");
  });

  it("refuses members and cross-tenant callers", async () => {
    const tenant = await createTenant("rename-perm", "growth");
    const other = await createTenant("rename-perm-other", "growth");

    await expect(
      renameOrganizationSlug(tenant.actors.member, {
        orgId: tenant.org.id,
        slug: "rename-perm-new",
      }),
    ).rejects.toBeInstanceOf(PermissionDeniedError);

    await expect(
      renameOrganizationSlug(other.actors.owner, {
        orgId: tenant.org.id,
        slug: "rename-perm-new",
      }),
    ).rejects.toBeInstanceOf(TenantScopeError);

    expect((await orgRepo.findOrgById(tenant.org.id))?.slug).toBe("rename-perm");
  });

  it("keeps every earlier slug for its own hold and lets the workspace reclaim one", async () => {
    const tenant = await createTenant("chain", "growth");

    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "chain-b",
    });
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "chain-c",
    });

    expect((await resolveOrgBySlug("chain"))?.slug).toBe("chain-c");
    expect((await resolveOrgBySlug("chain-b"))?.slug).toBe("chain-c");
    expect((await resolveOrgBySlug("chain-c"))?.id).toBe(tenant.org.id);

    const reclaimed = await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "chain",
    });
    expect(reclaimed.slug).toBe("chain");
    expect(await resolveOrgBySlug("chain-c")).toMatchObject({ slug: "chain" });
    expect(await resolveOrgBySlug("chain-b")).toMatchObject({ slug: "chain" });
    expect((await resolveOrgBySlug("chain"))?.slug).toBe("chain");
  });

  it("releases a retired slug at exactly ORG_SLUG_HOLD_DAYS and suffixes creation until then", async () => {
    vi.useFakeTimers();
    vi.setSystemTime(new Date("2026-01-01T00:00:00.000Z"));

    const tenant = await createTenant("hold", "growth");
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "hold-next",
    });

    const otherOwner = (await createTenant("hold-owner", "growth")).userIds.owner;

    vi.setSystemTime(new Date("2026-01-30T23:59:59.999Z"));
    expect((await resolveOrgBySlug("hold"))?.id).toBe(tenant.org.id);
    await expect(
      renameOrganizationSlug(
        (await orgRepo.findOrgBySlug("hold-owner"))
          ? (await createTenant("hold-blocker", "growth")).actors.owner
          : (await createTenant("hold-blocker", "growth")).actors.owner,
        {
          orgId: (await orgRepo.findOrgBySlug("hold-owner"))!.id,
          slug: "hold",
        },
      ),
    ).rejects.toBeInstanceOf(InvalidSlugError);

    const createdDuringHold = await createOrganization(otherOwner, {
      name: "Held During",
      slug: "hold",
      plan: "free",
    });
    expect(createdDuringHold.slug).not.toBe("hold");
    expect(createdDuringHold.slug.startsWith("hold-")).toBe(true);

    const release = new Date("2026-01-01T00:00:00.000Z");
    release.setUTCDate(release.getUTCDate() + ORG_SLUG_HOLD_DAYS);
    vi.setSystemTime(release);

    expect(await resolveOrgBySlug("hold")).toBeNull();
    expect(await orgRepo.findOrgBySlug("hold")).toBeNull();

    const taker = await createTenant("hold-taker", "growth");
    const taken = await renameOrganizationSlug(taker.actors.owner, {
      orgId: taker.org.id,
      slug: "hold",
    });
    expect(taken.slug).toBe("hold");
    expect((await resolveOrgBySlug("hold"))?.id).toBe(taker.org.id);

    const session = await resolveActorForOrg(principal(tenant), "hold");
    expect(session).toBeNull();
  });

  it("still records a single audit row when activity listeners are attached", async () => {
    const tenant = await createTenant("rename-listen", "growth");
    const detach = registerActivityListeners();
    await renameOrganizationSlug(tenant.actors.owner, {
      orgId: tenant.org.id,
      slug: "rename-listen-next",
    });
    expect((await auditRows(tenant)).items).toHaveLength(1);
    detach();
  });

  it("accepts the action in the audit-log filter schema", () => {
    const parsed = activityFilterSchema.safeParse({
      orgId: "01ARZ3NDEKTSV4RRFFQ69G5FAV",
      action: ["organization.slug_changed"],
      limit: 25,
      cursor: null,
    });
    expect(parsed.success).toBe(true);
  });
});
