it("releases a retired slug at exactly ORG_SLUG_HOLD_DAYS and suffixes creation until then", async () => {
  vi.useFakeTimers();
  vi.setSystemTime(new Date("2026-01-01T00:00:00.000Z"));

  const tenant = await createTenant("hold", "growth");
  await renameOrganizationSlug(tenant.actors.owner, {
    orgId: tenant.org.id,
    slug: "hold-next",
  });
  const rival = await createTenant("holdrival", "growth");

  vi.setSystemTime(new Date("2026-01-30T23:59:59.999Z"));
  expect((await resolveOrgBySlug("hold"))?.id).toBe(tenant.org.id);
  expect((await resolveActorForOrg(principal(tenant), "hold"))?.orgId).toBe(
    tenant.org.id,
  );
  await expect(
    renameOrganizationSlug(rival.actors.owner, {
      orgId: rival.org.id,
      slug: "hold",
    }),
  ).rejects.toBeInstanceOf(InvalidSlugError);
  expect((await orgRepo.findOrgById(rival.org.id))?.slug).toBe("holdrival");

  const createdDuringHold = await createOrganization(rival.userIds.owner, {
    name: "Held During",
    slug: "hold",
    plan: "free",
  });
  expect(createdDuringHold.slug).not.toBe("hold");

  const release = new Date("2026-01-01T00:00:00.000Z");
  release.setUTCDate(release.getUTCDate() + ORG_SLUG_HOLD_DAYS);
  vi.setSystemTime(release);

  expect(await resolveOrgBySlug("hold")).toBeNull();
  expect(await orgRepo.findOrgBySlug("hold")).toBeNull();
  expect(await resolveActorForOrg(principal(tenant), "hold")).toBeNull();

  const taken = await renameOrganizationSlug(rival.actors.owner, {
    orgId: rival.org.id,
    slug: "hold",
  });
  expect(taken.slug).toBe("hold");
  expect((await resolveOrgBySlug("hold"))?.id).toBe(rival.org.id);
  expect((await resolveOrgBySlug("hold-next"))?.id).toBe(tenant.org.id);
});

